void dfs(vector<int>& a, int i, vector<int>& cur, vector<vector<int>>& res) {
    if (i == (int)a.size()) { res.push_back(cur); return; }
    dfs(a, i + 1, cur, res);          // exclude a[i]
    cur.push_back(a[i]);              // include a[i]
    dfs(a, i + 1, cur, res);
    cur.pop_back();                   // backtrack
}

class Solution {
    vector<vector<int>> res; vector<int> path;
    void dfs(vector<int>& a, int start) {
        res.push_back(path);
        for (int i = start; i < (int)a.size(); i++) {
            path.push_back(a[i]);
            dfs(a, i + 1);
            path.pop_back();
        }
    }
public:
    vector<vector<int>> subsets(vector<int>& a) { dfs(a, 0); return res; }
};

class Solution:
    def subsets(self, a: list[int]) -> list[list[int]]:
        res, path = [], []
        def dfs(start):
            res.append(path[:])
            for i in range(start, len(a)):
                path.append(a[i])
                dfs(i + 1)
                path.pop()
        dfs(0)
        return res

class Solution {
    vector<vector<int>> res; vector<int> path;
    void dfs(vector<int>& a, int start) {
        res.push_back(path);
        for (int i = start; i < (int)a.size(); i++) {
            if (i > start && a[i] == a[i-1]) continue;
            path.push_back(a[i]);
            dfs(a, i + 1);
            path.pop_back();
        }
    }
public:
    vector<vector<int>> subsetsWithDup(vector<int>& a) {
        sort(a.begin(), a.end()); dfs(a, 0); return res;
    }
};

class Solution:
    def subsetsWithDup(self, a: list[int]) -> list[list[int]]:
        a.sort()
        res, path = [], []
        def dfs(start):
            res.append(path[:])
            for i in range(start, len(a)):
                if i > start and a[i] == a[i-1]:
                    continue
                path.append(a[i])
                dfs(i + 1)
                path.pop()
        dfs(0)
        return res

class Solution {
    vector<vector<int>> res; vector<int> path; int n, k;
    void dfs(int start) {
        if ((int)path.size() == k) { res.push_back(path); return; }
        for (int i = start; i <= n - (k - (int)path.size()) + 1; i++) {
            path.push_back(i);
            dfs(i + 1);
            path.pop_back();
        }
    }
public:
    vector<vector<int>> combine(int N, int K) { n = N; k = K; dfs(1); return res; }
};

class Solution:
    def combine(self, n: int, k: int) -> list[list[int]]:
        res, path = [], []
        def dfs(start):
            if len(path) == k:
                res.append(path[:]); return
            for i in range(start, n - (k - len(path)) + 2):
                path.append(i)
                dfs(i + 1)
                path.pop()
        dfs(1)
        return res

class Solution {
    vector<vector<int>> res; vector<int> path;
    void dfs(vector<int>& a, int start, int target) {
        if (target == 0) { res.push_back(path); return; }
        for (int i = start; i < (int)a.size(); i++) {
            if (a[i] > target) continue;
            path.push_back(a[i]);
            dfs(a, i, target - a[i]);   // reuse i
            path.pop_back();
        }
    }
public:
    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        sort(candidates.begin(), candidates.end());
        dfs(candidates, 0, target); return res;
    }
};

class Solution:
    def combinationSum(self, candidates: list[int], target: int) -> list[list[int]]:
        candidates.sort()
        res, path = [], []
        def dfs(start, remain):
            if remain == 0:
                res.append(path[:]); return
            for i in range(start, len(candidates)):
                if candidates[i] > remain:
                    break
                path.append(candidates[i])
                dfs(i, remain - candidates[i])
                path.pop()
        dfs(0, target)
        return res

class Solution {
    vector<string> res; string path; vector<string> M = {"","","abc","def","ghi","jkl","mno","pqrs","tuv","wxyz"};
    void dfs(string& digits, int idx) {
        if (idx == (int)digits.size()) { res.push_back(path); return; }
        for (char c : M[digits[idx] - '0']) {
            path.push_back(c);
            dfs(digits, idx + 1);
            path.pop_back();
        }
    }
public:
    vector<string> letterCombinations(string digits) {
        if (digits.empty()) return {};
        dfs(digits, 0); return res;
    }
};

class Solution:
    def letterCombinations(self, digits: str) -> list[str]:
        if not digits:
            return []
        M = {'2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz'}
        res, path = [], []
        def dfs(idx):
            if idx == len(digits):
                res.append("".join(path)); return
            for c in M[digits[idx]]:
                path.append(c)
                dfs(idx + 1)
                path.pop()
        dfs(0)
        return res
